```javascript
// Importing the required library
const Ajv = require("ajv");

// Initializing the Ajv instance
const ajv = new Ajv();

// Defining the JSON schema
const schema = {
    type: "object",
    properties: {
        menu: {
            type: "object",
            properties: {
                id: { type: "string" },
                value: { type: "string" },
                popup: {
                    type: "object",
                    properties: {
                        menuitem: {
                            type: "array",
                            items: {
